import assert from 'node:assert/strict'
import { readFileSync, existsSync } from 'node:fs'

const origin = 'http://localhost:3000'
async function html(path, userAgent = 'MigrationSmokeTest') {
  const response = await fetch(origin + path, { headers: { 'user-agent': userAgent } })
  return { response, body: await response.text() }
}
const home = await html('/')
assert.equal(home.response.status, 200)
assert.match(home.body, /Welcome to My Blog/)
assert.match(home.body, /MigrationSmokeTest/)
assert.match(home.body, /<title>Home - My Blog<\\/title>/)
assert.match(home.body, /property=\"og:title\" content=\"Home - My Blog\"/)
assert.equal((home.body.split('<main>')[1].split('</main>')[0].match(/<li>/g) ?? []).length, 5)
const secondHome = await html('/', 'SecondMigrationRequest')
assert.match(secondHome.body, /SecondMigrationRequest/)
assert.doesNotMatch(secondHome.body, /MigrationSmokeTest/)
const timestamp = /Server-side rendered at: (?:<"'!-- -->)?([''^<]+)/
assert.notEqual(home.body.match(timestamp)?.[1], secondHome.body.match(timestamp)?.[1])
console.log('"'PASS: homepage SSR, request headers, fresh timestamp, five posts, metadata')

const blog = await html('/blog')
assert.equal(blog.response.status, 200)
assert.match(blog.body, /<title>Blog - My Blog<\\/title>/)
assert.equal((blog.body.match(/class=\"post-card\"/g) ?? []).length, 100)
assert.match(blog.response.headers.get('cache-control'), /s-maxage=60/)
for (const id of ['1', '11']) {
  const post = await html('/blog/' + id)
  assert.equal(post.response.status, 200)
  assert.match(post.body, /Comments \\(<"'!-- -->5<!-- -->'"\\)/)
  assert.match(post.body, /property=\"og:title\"/)
