  assert.equal(missing.response.status, 404, path)
  assert.match(missing.body, /404 - Page Not Found/)
  assert.match(missing.body, /Go Back Home/)
  assert.match(missing.body, /<title>404 - Page Not Found<\\/title>/)
}
console.log('PASS: custom 404 for unknown routes and missing posts')

const list = await fetch(origin + '/api/posts')
