/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync, existsSync } from 'node:fs'
const origin = 'http://localhost:3000'
const jsonRequest = (method, data) => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) })
const list = await fetch(origin + '/api/posts')
assert.equal(list.status, 200)
assert.equal((await list.json()).length, 2)
const created = await fetch(origin + '/api/posts', jsonRequest('POST', { title: 'Smoke test', content: 'Post content' }))
assert.equal(created.status, 201)
assert.equal((await created.json()).title, 'Smoke test')
const invalid = await fetch(origin + '/api/posts', jsonRequest('POST', {}))
assert.equal(invalid.status, 400)
const item = await fetch(origin + '/api/posts/42')
assert.equal(item.status, 200)
assert.equal((await item.json()).id, 42)
const updated = await fetch(origin + '/api/posts/42', jsonRequest('PUT', { title: 'Updated' }))
assert.equal(updated.status, 200)
const { updatedAt, ...updatedPost } = await updated.json()
assert.ok(Number.isFinite(Date.parse(updatedAt)))
assert.deepEqual(updatedPost, { id: 42, title: 'Updated', content: 'Updated content for post 42' })
const deleted = await fetch(origin + '/api/posts/42', { method: 'DELETE' })
assert.equal(deleted.status, 200)
assert.deepEqual(await deleted.json(), { message: 'Post 42 deleted successfully' })
for (const [path, method] of [['/api/posts', 'PUT'], ['/api/posts/42', 'POST']]) {
  assert.equal((await fetch(origin + path, { method })).status, 405)
}
for (const path of ['/api/posts', '/api/posts/42']) {
  const options = await fetch(origin + path, { method: 'OPTIONS' })
  assert.equal(options.status, 204)
  assert.match(options.headers.get('allow'), /GET/)
  const head = await fetch(origin + path, { method: 'HEAD' })
  assert.equal(head.status, 200)
  assert.equal(await head.text(), '')
}
console.log('PASS: API GET/POST/PUT/DELETE, validation, automatic 405/OPTIONS/HEAD')
const manifest = JSON.parse(readFileSync('.next/prerender-manifest.json', 'utf8'))
assert.equal(manifest.routes['/blog'].initialRevalidateSeconds, 60)
for (let id = 1; id <= 10; id++) {
  assert.equal(manifest.routes['/blog/' + id].initialRevalidateSeconds, 300)
}
assert.equal(manifest.dynamicRoutes['/blog/[id]'].fallback, null)
assert.equal(existsSync('pages'), false)
console.log('PASS: prerender manifest confirms 60s/300s ISR and blocking fallback; pages directory absent')
NODE"

